using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RegalKhepreshOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/RegalKhepreshOmenData")]
public class RegalKhepreshOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.TaintedKhepreshOmenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
		ReferenceSingleton<SothisOmensHandler>.Instance.TaintedKhepreshReliefOmenAction = (int effectAmount) => effectAmount + ActionValue;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.TaintedKhepreshOmenAction = null;
		ReferenceSingleton<SothisOmensHandler>.Instance.TaintedKhepreshReliefOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAtTheEndOfYourTurn().LowercaseFirst().RemoveLast(), ActionValue);
	}
}
